operation.add:
$data['manufacturer_id'] = $manufacturer_id;
$data['product_total'] = $product_total;
$data['manufacturers_list'] = $this->url->link('product/manufacturer');
$_mfr_cats_sql = "SELECT c.category_id, cd.name, COUNT(DISTINCT p.product_id) as total";
$_mfr_cats_sql .= " FROM " . DB_PREFIX . "product p";
$_mfr_cats_sql .= " LEFT JOIN " . DB_PREFIX . "product_to_category p2c ON (p.product_id = p2c.product_id)";
$_mfr_cats_sql .= " LEFT JOIN " . DB_PREFIX . "category c ON (p2c.category_id = c.category_id)";
$_mfr_cats_sql .= " LEFT JOIN " . DB_PREFIX . "category_description cd ON (c.category_id = cd.category_id AND cd.language_id = '" . (int)$this->config->get('config_language_id') . "')";
$_mfr_cats_sql .= " WHERE p.manufacturer_id = '" . (int)$manufacturer_id . "' AND p.status = '1' AND c.status = '1'";
$_mfr_cats_sql .= " GROUP BY c.category_id HAVING total > 0 ORDER BY total DESC LIMIT 10";
$_mfr_cats = $this->db->query($_mfr_cats_sql);
$data['manufacturer_categories'] = array();
$data['manufacturer_categories'][] = array('name' => 'Все товары', 'href' => $this->url->link('product/manufacturer/info', 'manufacturer_id=' . $manufacturer_id), 'count' => $product_total);
foreach ($_mfr_cats->rows as $_mc) {
	$data['manufacturer_categories'][] = array('name' => $_mc['name'], 'href' => $this->url->link('product/manufacturer/info', 'manufacturer_id=' . $manufacturer_id . '&category_id=' . $_mc['category_id']), 'count' => (int)$_mc['total']);
}
